import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B9qR_F1m.js";const c=JSON.parse('{"title":"Speichern & Export","description":"","frontmatter":{},"headers":[],"relativePath":"dcs/speichern.md","filePath":"dcs/speichern.md"}'),a={name:"dcs/speichern.md"};function d(s,e,o,h,l,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="speichern-export" tabindex="-1">Speichern &amp; Export <a class="header-anchor" href="#speichern-export" aria-label="Permalink to &quot;Speichern &amp; Export&quot;">​</a></h1><p>Es gibt zwei Wege, Ergebnisse aus Shardwing zu holen: <strong>Speichern</strong> schreibt alles in die Mission, <strong>Export</strong> erzeugt Unterlagen zum Verteilen, ohne die .miz anzufassen.</p><h2 id="speichern" tabindex="-1">Speichern <a class="header-anchor" href="#speichern" aria-label="Permalink to &quot;Speichern&quot;">​</a></h2><p><kbd>⌘S</kbd> / <kbd>Strg+S</kbd> oder der Knopf <strong>Speichern</strong>.</p><table tabindex="0"><thead><tr><th></th><th>Desktop-App</th><th>Browser</th></tr></thead><tbody><tr><td><strong>Speichern</strong></td><td>schreibt die .miz an ihren Platz zurück, alte Version kommt in die Sicherung</td><td>Download (in Chrome/Edge je nach Dialog direkt in die Datei)</td></tr><tr><td><strong>Speichern unter</strong></td><td><kbd>⌘⇧S</kbd> / <kbd>Strg+Shift+S</kbd></td><td>–</td></tr></tbody></table><p>Beim Schließen mit ungespeicherten Änderungen fragt Shardwing nach.</p><h3 id="was-in-die-miz-geschrieben-wird" tabindex="-1">Was in die .miz geschrieben wird <a class="header-anchor" href="#was-in-die-miz-geschrieben-wird" aria-label="Permalink to &quot;Was in die .miz geschrieben wird&quot;">​</a></h3><ul><li><strong>Cartridges</strong> als Dateien und ihre Zuordnung zu den Flugzeugen</li><li><strong>Routen</strong> (Wegpunkte, Höhen, Geschwindigkeiten, Zeiten)</li><li><strong>Beladung</strong>, Fuel, Chaff/Flare, Gun</li><li><strong>Zeichnungen</strong> auf ihren Ebenen, Threat-Ringe auf F10</li><li><strong>Kneeboard-Seiten</strong>, die du eingebettet hast</li><li><strong>Bullseye</strong>, wenn du ihn versetzt hast</li><li><strong>IADS</strong>: Gruppennamen, Static-Objekte, Skripte und Lade-Trigger (wenn eingeschaltet)</li></ul><h3 id="verlustfrei" tabindex="-1">Verlustfrei <a class="header-anchor" href="#verlustfrei" aria-label="Permalink to &quot;Verlustfrei&quot;">​</a></h3><p>Shardwing liest die Mission mit einem eigenen, verlustfreien Lua-Parser. <strong>Was es nicht bearbeitet, bleibt Byte für Byte erhalten</strong>: Trigger, Skripte, Einheiten, Wetter, Felder von Mods, die Shardwing gar nicht kennt. Öffnen und unverändert speichern ergibt dieselbe Datei.</p><h3 id="planungsdaten" tabindex="-1">Planungsdaten <a class="header-anchor" href="#planungsdaten" aria-label="Permalink to &quot;Planungsdaten&quot;">​</a></h3><p>Was DCS nicht kennt – Timing, eigene Callsigns, Angriffe, Intel-Freigaben, Comm Plan, Kneeboard-Entwürfe – legt Shardwing als eigene Datei <code>Shardwing/planner.json</code> in die .miz. DCS ignoriert sie.</p><div class="warning custom-block"><p class="custom-block-title">Nach dem Mission Editor</p><p>Speicherst du die Mission danach im <strong>Mission Editor</strong>, kann der ME diese Zusatzdatei verwerfen. Dann gehen nur die Planungsdaten verloren, nie die Mission selbst. Am sichersten: im ME fertig bauen, dann in Shardwing planen – oder nach ME-Änderungen die zuletzt von Shardwing gespeicherte Version als Ausgangspunkt behalten. Ist die Mission in der Desktop-App offen, während du im ME speicherst, behält Shardwing die Planungsdaten (siehe <a href="#zusammen-mit-dem-mission-editor">Zusammen mit dem Mission Editor</a>).</p></div><h2 id="zusammen-mit-dem-mission-editor" tabindex="-1">Zusammen mit dem Mission Editor <a class="header-anchor" href="#zusammen-mit-dem-mission-editor" aria-label="Permalink to &quot;Zusammen mit dem Mission Editor&quot;">​</a></h2><p>In der <strong>Desktop-App</strong> merkt Shardwing selbst, wenn die geöffnete .miz auf der Platte neu gespeichert wird – etwa vom DCS Mission Editor. Nach etwa zwei Sekunden lädt es die Mission neu und meldet „aus DCS neu geladen“. Ausgewählter Flight und Bereich bleiben stehen.</p><ul><li><strong>Deine ungespeicherten Änderungen bleiben erhalten</strong> und liegen danach auf der neuen Fassung. Hat der ME dasselbe geändert (z. B. dieselbe Route), gilt die Fassung aus dem ME.</li><li><strong>Fehlen die Planungsdaten</strong> in der neuen Datei, weil der ME sie verworfen hat, behält Shardwing sie und schreibt sie beim nächsten Speichern wieder hinein.</li></ul><p><strong>Andersherum geht es nicht von selbst:</strong> Der Mission Editor bemerkt nicht, wenn Shardwing die Datei speichert. Öffne die Mission danach im ME neu. Speicherst du im ME die alte, noch offene Fassung, überschreibt sie, was Shardwing gespeichert hat.</p><table tabindex="0"><thead><tr><th>Schritt</th><th>Wo</th></tr></thead><tbody><tr><td>Einheiten, Trigger, Wetter bauen und speichern</td><td>ME – Shardwing lädt nach</td></tr><tr><td>Planen und speichern</td><td>Shardwing</td></tr><tr><td>Weiter im ME</td><td>Mission dort <strong>neu öffnen</strong>, dann ändern</td></tr></tbody></table><p>Im Browser gibt es das nicht: Shardwing kann dort die Datei nicht beobachten. Mission nach ME-Änderungen neu öffnen.</p><h2 id="ausgeben" tabindex="-1">Ausgeben <a class="header-anchor" href="#ausgeben" aria-label="Permalink to &quot;Ausgeben {#ausgeben}&quot;">​</a></h2><p><strong>Ausgeben</strong> am Ende der Leiste oben (<kbd>⌘E</kbd> / <kbd>Strg+E</kbd>, auch im Logo-Menü) zeigt auf einem Blatt alles, was die App verlässt. Oben wählst du, was mitgeht: die Kneeboard-Seiten des Pakets (ohne Deckblatt) und die Lineup Cards der angehakten Flights – standardmäßig alle blauen.</p><p><strong>Für DCS</strong> (nur Designer): <strong>Speichern und einbetten</strong> rendert alle gewählten Seiten, bettet sie in die .miz ein und speichert in einem Schritt. Gleichnamige Seiten in der .miz werden ersetzt; ein Index wird zuletzt gerechnet und zählt die neuen Seiten schon mit. <strong>Nur speichern</strong> schreibt die Mission, ohne die Kneeboards anzufassen. Bei einer geteilten Mission heißt der Knopf <strong>In die Server-.miz einbetten</strong>. Hat ein Flight Threats nur für sich und fliegt ein zweiter denselben Typ, warnt das Blatt: Kneeboards gelten in DCS pro Flugzeugtyp.</p><p>Einzelne Seiten bettest du wie bisher an Ort und Stelle ein (Kneeboards, Lineup Card).</p><p><strong>Für die Piloten</strong> – der frühere Export:</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Kneeboard-Pakete für die gewählten Flights, ohne die .miz zu ändern.</p><table tabindex="0"><thead><tr><th>Knopf</th><th>Ergebnis</th></tr></thead><tbody><tr><td><strong>ZIP: PDF + Kneeboard-Ordner</strong></td><td>Pro Flight ein PDF und ein Ordner <code>Kneeboard/&lt;Typ&gt;/</code> mit den Seiten als Bilder</td></tr><tr><td><strong>Ein PDF für alle</strong></td><td>Alle Seiten aller gewählten Flights in einer Datei, z. B. fürs Briefing</td></tr></tbody></table><p><strong>Kneeboards beilegen</strong> packt die Paket-Kneeboards dazu, die für den jeweiligen Flugzeugtyp bestimmt sind.</p><h3 id="kneeboard-ordner-verwenden" tabindex="-1">Kneeboard-Ordner verwenden <a class="header-anchor" href="#kneeboard-ordner-verwenden" aria-label="Permalink to &quot;Kneeboard-Ordner verwenden&quot;">​</a></h3><p>Den Ordner <code>Kneeboard</code> aus dem ZIP nach <code>Saved Games\\DCS\\</code> kopieren (bzw. <code>Saved Games\\DCS.openbeta\\</code>). DCS zeigt die Seiten dann im Kneeboard dieses Typs – in jeder Mission. <strong>OpenKneeboard</strong> liest denselben Ordner.</p><p>Für einen einzelnen Flight gibt es dieselben Downloads auch in der <a href="/bereiche/uebersicht#downloads">Übersicht</a>.</p><h3 id="einzelne-dateien" tabindex="-1">Einzelne Dateien <a class="header-anchor" href="#einzelne-dateien" aria-label="Permalink to &quot;Einzelne Dateien&quot;">​</a></h3><ul><li><strong>Cartridge</strong> als <code>.dtc</code>: im <a href="/bereiche/dtc">DTC-Editor</a> → <strong>.dtc exportieren</strong>. Ablegen unter <code>Saved Games\\DCS\\DTC</code>.</li><li><strong>Seiten</strong> als PNG oder PDF: in <a href="/bereiche/lineup-card">Lineup Card</a> und <a href="/bereiche/kneeboards">Kneeboards</a>.</li></ul><h2 id="wann-was" tabindex="-1">Wann was? <a class="header-anchor" href="#wann-was" aria-label="Permalink to &quot;Wann was?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Weg</th></tr></thead><tbody><tr><td>Ihr fliegt auf einem Server, alle bekommen dieselbe Mission</td><td><strong>Speichern</strong> – alles steckt in der .miz</td></tr><tr><td>Ein Flight hat Intel, die andere nicht sehen sollen</td><td><strong>Export</strong> dieses Flights, nicht einbetten</td></tr><tr><td>Briefing per Bildschirm oder ausgedruckt</td><td><strong>Ein PDF für alle</strong></td></tr><tr><td>Piloten wollen ihre Seiten in OpenKneeboard</td><td><strong>ZIP</strong></td></tr></tbody></table>',35)])])}const b=n(a,[["render",d]]);export{c as __pageData,b as default};
